window.localBattleArt = {"noise":"data:image/png;base64,","fog":{"common":"#define FOG_MOBILE\n#define saturate(x) clamp(x,0.0,1.0)\n#define _AlphaHalf 1.0\n#define _AlphaMultiply 1.0\n#define _AlphaOuter 0.0\n#define _AlphaPower 0.5\n#define _BaseCloudsIntensity 1.5\n#define _BaseCloudsScale 0.8\n#define _BaseScale 3.0\n#define _BaseSpeed 0.02\n#define _CloudsAScale 0.5\n#define _CloudsBScale 1.0\n#define _CloudsOpacityHalf 0.8\n#define _CloudsOpacityOuter 0.8\n#define _DarkTintFalloff 0.8\n#define _DetailCloudsPower 1.0\n#define _DirectionFalloff 1.0\n#define _DirectionIntensity 1.0\n#define _DirectionalMaskClouds 0.35\n#define _DirectionlessMaskIntensity 0.5\n#define _DisplacementHeight 1.5\n#define _EmissionStrength 0.25\n#define _FresnelOpacity 0.35\n#define _FresnelPower 2.2\n#define _FresnelScale 2.0\n#define _OffsetEdge 1.0\n#define _OffsetHalf 3.0\n#define _OffsetOutside 0.5\n#define _SmoothstepMax 0.6\n#define _SmoothstepMin 0.0\n#define _BaseCloudsRemap vec4(-0.4,1.71,0.08,0.7)\n#define _BaseCloudsSpeed vec4(-0.5,-0.8,0.0,0.0)\n#define _CloudsASpeed vec4(0.2,0.1,0.0,0.0)\n#define _CloudsBSpeed vec4(-0.15,-1.0,0.0,0.0)\n#define _Color vec4(0.652141511,0.672827066,0.707150741,1.0)\n#define _ColorPeaks vec4(0.787412289,0.872396616,1.0,0.0)\n#define _ColorValleys vec4(0.200070002,0.267622132,0.355935924,0.0)\n#define _DarkTint vec4(0.0980405411,0.108968347,0.130775471,0.0)\n#define _DetailCloudsRemap vec4(0.16,2.0,-0.2,1.0)\n#define _Direction vec4(-0.562558176,0.594331352,-0.574716053,1.0)\n#define _DirectionColor vec4(0.522521554,0.391404128,0.274768624,1.0)\nfloat Remap(float value, vec4 range)\n            {\n                return (value - range.x) * (range.w - range.z) / (range.y - range.x) + range.z;\n            }\n            float CloudValue(vec2 xz, bool vertexStage)\n            {\n                vec2 uv = xz * (0.01 * _BaseScale);\n                float scroll = time * _BaseSpeed;\n                vec2 aUV = uv * _CloudsAScale + _CloudsASpeed.xy * scroll;\n                vec2 bUV = uv * _CloudsBScale + _CloudsBSpeed.xy * scroll;\n                vec2 baseUV = uv * _BaseCloudsScale + _BaseCloudsSpeed.xy * scroll;\n                float a, b, baseCloud;\n                #if defined(FOG_MOBILE)\n                if (vertexStage)\n                {\n                    baseCloud = texture2D(clouds,baseUV).r;\n                    // Mean detail of the source noise keeps the large-scale displacement level.\n                    a = b = 0.64;\n                }\n                else\n                {\n                    baseCloud = texture2D(clouds,baseUV).r;\n                    a = texture2D(clouds,aUV).g;\n                    b = 0.64;\n                }\n                #else\n                if (vertexStage)\n                {\n                    a = texture2D(clouds,aUV).g;\n                    b = texture2D(clouds,bUV).g;\n                    baseCloud = texture2D(clouds,baseUV).r;\n                }\n                else\n                {\n                    a = texture2D(clouds,aUV).g;\n                    b = texture2D(clouds,bUV).g;\n                    baseCloud = texture2D(clouds,baseUV).r;\n                }\n                #endif\n                float detail = pow(saturate((a+b)*0.5), _DetailCloudsPower);\n                detail = smoothstep(_SmoothstepMin, _SmoothstepMax, abs(Remap(detail, _DetailCloudsRemap)));\n                float density = Remap(baseCloud, _BaseCloudsRemap) * _BaseCloudsIntensity + detail;\n                return max(0.1, smoothstep(0.0, _BaseCloudsIntensity, density));\n            }\n            ","light":"float fresnel = pow(max(0.0001, 1.0 - dot(normalize(vec3(0.,1.,0.)), view)), _FresnelPower);\n                fresnel = smoothstep(0.0, 1.0, fresnel * _FresnelScale) * cloud * _FresnelOpacity;\n                float sun = pow(saturate(dot(cameraRay, _Direction.xyz) * 0.5 + 0.5), _DirectionFalloff);\n                sun = mix(_DirectionlessMaskIntensity, sun, _DirectionIntensity);\n                sun = mix(sun, sun * cloud, _DirectionalMaskClouds);\n                vec3 tint = mix(_ColorValleys.rgb, _ColorPeaks.rgb, cloud) * _Color.rgb;\n                vec3 lit = mix(tint, _DirectionColor.rgb, sun);\n                float dark = saturate(pow(abs(1.0 - bands.y), _DarkTintFalloff));\n                vec3 darkLit = lit * _DarkTint.rgb;\n                vec3 rgb = mix(tint + fresnel * (1.0 - sun), darkLit, dark)\n                           + _EmissionStrength * mix(lit, darkLit, dark);\n\n                "},"cap":"data:image/png;base64,","enemy":"data:model/gltf-binary;base64,","edgeClouds":"data:image/webp;base64,"};
